import { Component, OnInit, ChangeDetectorRef } from '@angular/core';
import { RegisterService, RegisterRequest, RegisterResponse, UsernameCheckResponse, PasswordValidationRequest, PasswordValidationResponse, EmailValidationRequest, EmailValidationResponse } from './register.service';

interface Task {
  description: string;
  roleName: string;
  selected: boolean;
}

@Component({
  selector: 'app-register',
  templateUrl: './register.component.html',
  styleUrls: ['./register.component.css']
})
export class RegisterComponent implements OnInit {
  name: string = '';
  username: string = '';
  email: string = '';
  password: string = '';
  confirmPassword: string = '';
  tasks: Task[] = [
    { description: 'Manage portfolios and transactions', roleName: 'Инвеститор', selected: false },
    { description: 'Analyze data trends', roleName: 'Аналитичар', selected: false },
    { description: 'Filter and compare current and historic data trends', roleName: 'Аналитичар', selected: false },
    { description: 'View current and historic data trends', roleName: 'Обичен корисник', selected: false },
    { description: 'Do basic filtering and limited searching', roleName: 'Обичен корисник', selected: false }
  ];
  roleNames: string[] = [];
  response: RegisterResponse | null = null;
  generalError: string | null = null;
  usernameError: string | null = null;
  emailError: string | null = null;
  passwordError: string | null = null;
  confirmPasswordError: string | null = null;
  isUsernameValid: boolean = true;
  isEmailValid: boolean = true;
  isPasswordValid: boolean = true;
  isEmailVerified: boolean = false;

  constructor(
    private registerService: RegisterService,
    private cdr: ChangeDetectorRef
  ) { }

  ngOnInit(): void {
    this.checkEmailVerification();
    this.cdr.detectChanges();
  }

  validateUsername(): void {
    if (this.username.trim() === '') {
      this.usernameError = null;
      this.isUsernameValid = false;
      return;
    }
    this.registerService.checkUsername(this.username).subscribe({
      next: (response: UsernameCheckResponse) => {
        this.isUsernameValid = !response.exists;
        this.usernameError = response.exists ? 'Username already exists' : null;
      },
      error: (err: any) => {
        console.error('Username check failed:', err);
        this.isUsernameValid = true;
        this.usernameError = null;
      }
    });
  }

  validateEmail(): void {
    if (this.email.trim() === '') {
      this.emailError = null;
      this.isEmailValid = false;
      return;
    }
    this.registerService.validateEmail({ email: this.email }).subscribe({
      next: (response: EmailValidationResponse) => {
        this.isEmailValid = response.isValid;
        this.emailError = response.isValid ? null : response.message;
      },
      error: (err: any) => {
        console.error('Email validation failed:', err);
        this.isEmailValid = true;
        this.emailError = null;
      }
    });
  }

  validatePassword(): void {
    if (this.password.trim() === '' || this.confirmPassword.trim() === '') {
      this.passwordError = null;
      this.confirmPasswordError = null;
      this.isPasswordValid = false;
      return;
    }
    this.registerService.validatePassword({ password: this.password, confirmPassword: this.confirmPassword }).subscribe({
      next: (response: PasswordValidationResponse) => {
        this.isPasswordValid = response.isValid;
        if (!response.isValid) {
          if (response.message.includes('do not match')) {
            this.passwordError = null;
            this.confirmPasswordError = response.message;
          } else {
            this.passwordError = response.message;
            this.confirmPasswordError = null;
          }
        } else {
          this.passwordError = null;
          this.confirmPasswordError = null;
        }
      },
      error: (err: any) => {
        console.error('Password validation failed:', err);
        this.isPasswordValid = true;
        this.passwordError = null;
        this.confirmPasswordError = null;
      }
    });
  }

  updateRoleNames(): void {
    const selectedRoles = this.tasks.filter(task => task.selected).map(task => task.roleName);
    this.roleNames = [...new Set(selectedRoles)];
  }

  isFormValid(): boolean {
    return this.name.trim() !== '' &&
      this.username.trim() !== '' &&
      this.email.trim() !== '' &&
      this.password.trim() !== '' &&
      this.confirmPassword.trim() !== '' &&
      this.roleNames.length > 0 &&
      this.isEmailValid &&
      this.isPasswordValid;
  }

  register(): void {
    if (!this.isFormValid()) {
      this.generalError = 'Please fill all fields correctly and select at least one task.';
      return;
    }

    const request: RegisterRequest = {
      name: this.name,
      username: this.username,
      email: this.email,
      password: this.password,
      confirmPassword: this.confirmPassword,
      roleNames: this.roleNames
    };

    this.registerService.register(request).subscribe({
      next: (response: RegisterResponse) => {
        this.response = response;
        this.generalError = null;
        
        this.resetForm();
      },
      error: (err: any) => {
        console.error('Registration error: ', err);
        this.response = null;
        this.generalError = err.error?.message || 'Registration failed';
      }
    });
  }

  resetForm(): void {
    this.name = '';
    this.username = '';
    this.email = '';
    this.password = '';
    this.confirmPassword = '';
    this.tasks.forEach(task => task.selected = false);
    this.roleNames = [];
    this.usernameError = null;
    this.emailError = null;
    this.passwordError = null;
    this.confirmPasswordError = null;
    this.isUsernameValid = true;
    this.isEmailValid = true;
    this.isPasswordValid = true;
  }

  clearSuccessMessage(): void {
    this.response = null;
    this.resetForm();
  }

  checkEmailVerification(): void {
    const urlParams = new URLSearchParams(window.location.search);
    const verified = urlParams.get('verified');
    if (verified === 'true') {
      this.isEmailVerified = true;
      this.generalError = null;
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }
}
<!DOCTYPE html>
<html>
<head>
  <link href="https://cdn.jsdelivr.net/npm/tailwindcss@2.2.19/dist/tailwind.min.css" rel="stylesheet">
</head>
<body>
  <div class="min-h-screen flex items-center justify-center bg-gray-100 py-8">
    <div class="bg-white p-8 rounded-lg shadow-lg w-full max-w-3xl">
      <div *ngIf="response && !isEmailVerified" class="mb-6 p-4 bg-yellow-100 border border-yellow-300 rounded-md animate-fade-in flex justify-between items-center">
        <div>
          <p class="text-green-700 font-medium">Registration successful</p>
          <p class="text-green-700 text-sm mt-1">Please check your email to verify your account.</p>
        </div>
        <button (click)="clearSuccessMessage()" class="text-green-700 hover:text-green-900">
          <svg class="h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
            <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M6 18L18 6M6 6l12 12"></path>
          </svg>
        </button>
      </div>
      <div *ngIf="isEmailVerified" class="mb-6 p-4 bg-green-100 border border-green-300 rounded-md animate-fade-in">
        <p class="text-green-700 font-medium">Email successfully verified. You can now log in.</p>
      </div>
      <h2 class="text-2xl font-bold text-center text-gray-800 mb-6">Register</h2>
      <div class="register-container">
        <div class="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label for="name" class="block text-sm font-medium text-gray-700">Name</label>
            <input id="name" [(ngModel)]="name" placeholder="Enter Name" required
                   class="mt-1 w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition duration-200" />
          </div>
          <div>
            <label for="username" class="block text-sm font-medium text-gray-700">Username</label>
            <input id="username" [(ngModel)]="username" placeholder="Enter Username" required
                   (ngModelChange)="validateUsername()"
                   class="mt-1 w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition duration-200" />
            <div *ngIf="usernameError" class="error mt-2 p-2 bg-red-100 border border-red-300 rounded-md animate-fade-in">
              <p class="text-red-700 text-sm">{{ usernameError }}</p>
            </div>
          </div>
          <div>
            <label for="email" class="block text-sm font-medium text-gray-700">Email</label>
            <input id="email" type="email" [(ngModel)]="email" placeholder="Enter Email" required
                   (ngModelChange)="validateEmail()"
                   class="mt-1 w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition duration-200" />
            <div *ngIf="emailError" class="error mt-2 p-2 bg-red-100 border border-red-300 rounded-md animate-fade-in">
              <p class="text-red-700 text-sm">{{ emailError }}</p>
            </div>
          </div>
          <div>
            <label for="password" class="block text-sm font-medium text-gray-700">Password</label>
            <input id="password" type="password" [(ngModel)]="password" placeholder="Enter Password" required
                   (ngModelChange)="validatePassword()"
                   class="mt-1 w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition duration-200" />
            <div *ngIf="passwordError" class="error mt-2 p-2 bg-red-100 border border-red-300 rounded-md animate-fade-in">
              <p class="text-red-700 text-sm">{{ passwordError }}</p>
            </div>
          </div>
          <div>
            <label for="confirmPassword" class="block text-sm font-medium text-gray-700">Confirm Password</label>
            <input id="confirmPassword" type="password" [(ngModel)]="confirmPassword" placeholder="Confirm Password" required
                   (ngModelChange)="validatePassword()"
                   class="mt-1 w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500 transition duration-200" />
            <div *ngIf="confirmPasswordError" class="error mt-2 p-2 bg-red-100 border border-red-300 rounded-md animate-fade-in">
              <p class="text-red-700 text-sm">{{ confirmPasswordError }}</p>
            </div>
          </div>
        </div>
        <div class="mt-4">
          <label class="block text-sm font-medium text-gray-700">What would you like to do on the site?</label>
          <div class="grid grid-cols-1 sm:grid-cols-2 gap-2 mt-2">
            <div *ngFor="let task of tasks; let i = index" class="task-checkbox flex items-center space-x-2">
              <input type="checkbox"
                     [id]="'task-' + i"
                     [(ngModel)]="task.selected"
                     (change)="updateRoleNames()"
                     class="h-5 w-5 text-blue-600 focus:ring-blue-500 border-gray-300 rounded transition duration-200" />
              <label [for]="'task-' + i" class="text-gray-700">{{ task.description }}</label>
            </div>
          </div>
        </div>
        <button (click)="register()" [disabled]="!isFormValid()"
                class="mt-6 w-full bg-gradient-to-r from-blue-500 to-indigo-600 text-white py-2 px-4 rounded-md hover:from-blue-600 hover:to-indigo-700 transition duration-300 disabled:bg-gray-400 disabled:cursor-not-allowed">
          Register
        </button>
      </div>
      <div *ngIf="generalError" class="error mt-4 p-4 bg-red-100 border border-red-300 rounded-md animate-fade-in">
        <p class="text-red-700">{{ generalError }}</p>
      </div>
      <p class="login-link text-center mt-4 text-gray-600">
        Already have an account? <a [routerLink]="['/login']" class="text-blue-600 hover:text-blue-800 hover:underline">Log in</a>
      </p>
    </div>
  </div>
</body>
</html>
